-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Kann ich ohne Berufsbildungsgesetz ausgebildet werden?', 2, '[{"text": "Nein", "correct": true, "because": "BBiG regelt Ausbildung"}, {"text": "Ja", "correct": false, "because": "Gesetzliche Grundlage nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss mein Ausbildungsvertrag dem Berufsbildungsgesetz entsprechen?', 2, '[{"text": "Ja", "correct": true, "because": "BBiG gibt Vorgaben"}, {"text": "Nein", "correct": false, "because": "Pflicht zur Einhaltung"}]'),
('00000000-0000-0000-0000-000000000000', 'Regelt das Berufsbildungsgesetz meine Vergütung?', 2, '[{"text": "Ja", "correct": true, "because": "Mindeststandards vorgeschrieben"}, {"text": "Nein", "correct": false, "because": "BBiG sichert Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte das Berufsbildungsgesetz meine Arbeitszeit begrenzen?', 2, '[{"text": "Ja", "correct": true, "because": "Schutzvorschriften enthalten"}, {"text": "Nein", "correct": false, "because": "Regelt Arbeitsbedingungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Schützt das Berufsbildungsgesetz meine Rechte als Azubi?', 2, '[{"text": "Ja", "correct": true, "because": "Ziel des Gesetzes"}, {"text": "Nein", "correct": false, "because": "Rechtsschutz garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb das Berufsbildungsgesetz ignorieren?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlich bindend"}, {"text": "Ja", "correct": false, "because": "Verstoß strafbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das Berufsbildungsgesetz nur für IT-Berufe relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Ausbildungen"}, {"text": "Ja", "correct": false, "because": "Branchenübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte ich ohne Berufsbildungsgesetz weniger Urlaub haben?', 2, '[{"text": "Ja", "correct": true, "because": "BBiG sichert Mindestanspruch"}, {"text": "Nein", "correct": false, "because": "Gesetzlicher Schutz"}]'),
-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das Berufsbildungsgesetz hauptsächlich?', 2, '[{"text": "Berufsausbildung", "correct": true, "because": "Kern des Gesetzes"}, {"text": "Steuern", "correct": false, "because": "Anderes Gesetz"}, {"text": "Verkehr", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, das BBiG gilt nicht für uns. Wann stimmt das?', 3, '[{"text": "Nie", "correct": true, "because": "BBiG ist allgemein bindend"}, {"text": "Wenn wir keinen Vertrag haben", "correct": false, "because": "BBiG gilt trotzdem"}, {"text": "Bei privater Ausbildung", "correct": false, "because": "BBiG umfasst alles"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht gibt mir das Berufsbildungsgesetz?', 2, '[{"text": "Ordnungsgemäße Ausbildung", "correct": true, "because": "Hauptziel BBiG"}, {"text": "Freie Wochenenden", "correct": false, "because": "Nicht spezifisch"}, {"text": "Firmenwagen", "correct": false, "because": "Kein Anspruch"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, was das BBiG schützt. Was sage ich?', 3, '[{"text": "Rechte und Pflichten in der Ausbildung", "correct": true, "because": "Kern des Gesetzes"}, {"text": "Nur den Betrieb", "correct": false, "because": "Auch Azubis"}, {"text": "Nur Prüfungen", "correct": false, "because": "Umfassender"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was regelt das Berufsbildungsgesetz?', 4, '[{"text": "Ausbildungsverträge", "correct": true, "because": "Form und Inhalt"}, {"text": "Vergütung", "correct": true, "because": "Mindeststandards"}, {"text": "Prüfungen", "correct": true, "because": "Organisation"}, {"text": "Büroversorgung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte sichert mir das BBiG?', 3, '[{"text": "Vergütung", "correct": true, "because": "Gesetzlich"}, {"text": "Urlaub", "correct": true, "because": "Mindestanspruch"}, {"text": "Ausbildung", "correct": true, "because": "Qualitätssicherung"}, {"text": "Dienstwagen", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über meinen Vertrag. Was sagt das BBiG?', 3, '[{"text": "Schriftform erforderlich", "correct": true, "because": "Vorgabe"}, {"text": "IHK muss prüfen", "correct": true, "because": "Registrierung"}, {"text": "Mindestinhalte nötig", "correct": true, "because": "Regelung"}, {"text": "Mündlich gültig", "correct": false, "because": "Verstoß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten legt das BBiG dem Betrieb auf?', 4, '[{"text": "Ausbildung gewährleisten", "correct": true, "because": "Hauptpflicht"}, {"text": "Vergütung zahlen", "correct": true, "because": "Gesetzlich"}, {"text": "Vertrag melden", "correct": true, "because": "IHK-Pflicht"}, {"text": "Urlaub verbieten", "correct": false, "because": "Kein Recht"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das BBiG regelt meinen Urlaub. b) Es gilt nur für Azubis.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Urlaub ja, auch andere betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BBiG schützt meine Arbeitszeit. b) Es regelt meine Steuern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Arbeitszeit ja, Steuern nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BBiG fordert einen Vertrag. b) Es erlaubt unbezahlte Ausbildung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrag ja, Bezahlung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das BBiG sichert meine Ausbildung. b) Es gilt nur für Betriebe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausbildung ja, auch Azubis"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

